export function mustSegregate(a: string, b: string): boolean {
  const aPrimary = primaryClass(a);
  const bPrimary = primaryClass(b);

  // Try to look up both the full class and primary class
  const left = SEGREGATION[a] ?? SEGREGATION[aPrimary] ?? [];
  const right = SEGREGATION[b] ?? SEGREGATION[bPrimary] ?? [];

  // Check if b (or something with same primary class as b) is in left
  const bMatches = left.some(item => item === b || primaryClass(item) === bPrimary);
  // Check if a (or something with same primary class as a) is in right
  const aMatches = right.some(item => item === a || primaryClass(item) === aPrimary);

  return bMatches || aMatches;
}

